#!/usr/bin/env python3
"""T-007: death/{regions,voids,urns}.txt -> datapack functions (generated, do not edit):
  death/gen/region   sets storage last_ember:dt urn from scores #x #y #z and storage last_ember:dt dim
  death/gen/is_void  sets #void le.e 1 in void boxes or below y -64
  ash/gen/find_spot  nearest safe point within 8 blocks (sorted offsets), spawns the trail there
  urn/gen/register   builds and registers urns (idempotent)
Usage: python3 tools/gen_death.py [urns_file]
"""
import math, os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
F = os.path.join(ROOT, "datapack/data/last_ember/function")
def rows(path):
    for line in open(path, encoding="utf-8"):
        line = line.split("#", 1)[0].strip()
        if line: yield line.split()
def write(rel, lines):
    p = os.path.join(F, rel); os.makedirs(os.path.dirname(p), exist_ok=True)
    open(p, "w", encoding="utf-8").write("\n".join(lines) + "\n")
def box(x1, y1, z1, x2, y2, z2):
    return f"if score #x le.e matches {min(x1,x2)}..{max(x1,x2)} if score #y le.e matches {min(y1,y2)}..{max(y1,y2)} if score #z le.e matches {min(z1,z2)}..{max(z1,z2)}"
reg = ["# generated by tools/gen_death.py from death/regions.txt", 'data modify storage last_ember:dt urn set value "none"']
for r, urn, dim, *c in rows(os.path.join(ROOT, "death/regions.txt")):
    reg.append(f'execute if data storage last_ember:dt {{dim:"minecraft:{dim}"}} {box(*map(int, c))} run return run data modify storage last_ember:dt urn set value "{urn}"')
write("death/gen/region.mcfunction", reg)
vo = ["# generated by tools/gen_death.py from death/voids.txt", "scoreboard players set #void le.e 0", "execute if score #y le.e matches ..-65 run scoreboard players set #void le.e 1"]
for vid, dim, *c in rows(os.path.join(ROOT, "death/voids.txt")):
    vo.append(f'execute if data storage last_ember:dt {{dim:"minecraft:{dim}"}} {box(*map(int, c))} run scoreboard players set #void le.e 1')
write("death/gen/is_void.mcfunction", vo)
offs = sorted(((dx, dy, dz) for dx in range(-8, 9) for dy in range(-8, 9) for dz in range(-8, 9) if dx*dx + dy*dy + dz*dz <= 64),
              key=lambda o: (o[0]**2 + o[1]**2 + o[2]**2, -o[1], o[0], o[2]))
fs = ["# generated by tools/gen_death.py: nearest free spot (air-like here and above, solid below) within 8 blocks, nearest first"]
for dx, dy, dz in offs:
    fs.append(f"execute positioned ~{dx} ~{dy} ~{dz} if block ~ ~ ~ #last_ember:ash_free if block ~ ~1 ~ #last_ember:ash_free unless block ~ ~-1 ~ #last_ember:ash_free unless block ~ ~-1 ~ #last_ember:liquid run return run function last_ember:ash/spawn")
write("ash/gen/find_spot.mcfunction", fs)
urns = list(rows(sys.argv[1] if len(sys.argv) > 1 else os.path.join(ROOT, "death/urns.txt")))
ur = ["# generated by tools/gen_death.py: urns (built once their chunk is loaded)"]
for n, urn, dim, x, y, z in urns:
    ur.append(f'execute unless data storage last_ember:ash urns.{urn}.built in minecraft:{dim} if loaded {x} {y} {z} positioned {x} {y} {z} run function last_ember:urn/build {{n:{n},urn:"{urn}",x:{x},y:{y},z:{z},dim:"minecraft:{dim}"}}')
write("urn/gen/register.mcfunction", ur)
print(f"{len(reg)-2} region boxes, {len(vo)-3} voids, {len(offs)} search offsets, {len(urns)} urns")
